{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect Meeting Notes or Transcript",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Raw meeting notes", "Meeting transcript (if available)"],
        "outputs": ["Collected raw material for summary"]
      },
      {
        "id": "A2",
        "name": "Draft Meeting Summary",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Collected raw material for summary"],
        "outputs": ["Draft meeting summary including decisions, action items with owners, and deadlines"]
      },
      {
        "id": "A3",
        "name": "Identify Unclear Items",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Draft meeting summary"],
        "outputs": ["List of unclear or ambiguous items requiring confirmation"]
      },
      {
        "id": "A4",
        "name": "Confirm Unclear Items with Decision Owners",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["List of unclear or ambiguous items", "Contact details of decision owners"],
        "outputs": ["Clarified information for unclear items"]
      },
      {
        "id": "A5",
        "name": "Finalise Meeting Summary",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Draft meeting summary", "Clarified information (if applicable)"],
        "outputs": ["Final meeting summary with decisions, action items with owners, and deadlines"]
      },
      {
        "id": "A6",
        "name": "Determine Recipients",
        "actor": "Minute Taker or Unknown Role",
        "system": "Unknown",
        "inputs": ["Final meeting summary", "Relevant recipient list (source unknown)"],
        "outputs": ["Confirmed list of email recipients"]
      },
      {
        "id": "A7",
        "name": "Send Summary Email",
        "actor": "Minute Taker or Unknown Role",
        "system": "Email client (unknown)",
        "inputs": ["Final meeting summary", "Confirmed list of email recipients"],
        "outputs": ["Summary email delivered to relevant recipients"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are there unclear or ambiguous items in the draft summary?",
        "branches": [
          "Yes → Proceed to A4 (Confirm Unclear Items with Decision Owners)",
          "No → Proceed directly to A5 (Finalise Meeting Summary)"
        ]
      }
    ],
    "exceptions": [
      "Decision owner is unreachable for clarification, blocking finalisation of the summary",
      "No transcript or sufficient notes are available to draft the summary",
      "Recipient list cannot be determined, preventing email dispatch"
    ],
    "dependencies": [
      {
        "from": "A1",
        "to": "A2",
        "type": "control_flow"
      },
      {
        "from": "A2",
        "to": "A3",
        "type": "control_flow"
      },
      {
        "from": "A3",
        "to": "D1",
        "type": "control_flow"
      },
      {
        "from": "D1",
        "to": "A4",
        "type": "conditional"
      },
      {
        "from": "D1",
        "to": "A5",
        "type": "conditional"
      },
      {
        "from": "A4",
        "to": "A5",
        "type": "control_flow"
      },
      {
        "from": "A5",
        "to": "A6",
        "type": "control_flow"
      },
      {
        "from": "A6",
        "to": "A7",
        "type": "control_flow"
      }
    ]
  },
  "automation_opportunities": [
    {
      "target": "A1 - Collect Meeting Notes or Transcript",
      "rationale": "Transcription tools or meeting platform integrations can automatically capture and deliver transcripts at meeting end, reducing manual note collection effort.",
      "required_data": ["Meeting platform access", "Audio or transcript feed"],
      "constraints": ["Consent and privacy requirements for recording", "Meeting platform must support automated transcript export"],
      "confidence": "high"
    },
    {
      "target": "A2 - Draft Meeting Summary",
      "rationale": "AI-based summarisation tools can process transcripts or notes to extract decisions, action items, owners, and deadlines, significantly reducing manual drafting time.",
      "required_data": ["Structured or unstructured transcript", "Defined summary template with required fields"],
      "constraints": ["AI accuracy must be validated before sending", "Sensitive meeting content may restrict use of external AI services"],
      "confidence": "medium"
    },
    {
      "target": "A3 - Identify Unclear Items",
      "rationale": "Automated confidence scoring on AI-generated summaries can flag low-confidence extractions for human review, streamlining the identification of unclear items.",
      "required_data": ["AI-generated draft summary with confidence metadata"],
      "constraints": ["Requires AI tool that provides confidence or uncertainty signals"],
      "confidence": "medium"
    },
    {
      "target": "A6 - Determine Recipients",
      "rationale": "If the meeting attendee list is available from a calendar or meeting platform, it can be used to automatically populate the recipient list.",
      "required_data": ["Meeting attendee list from calendar or meeting platform"],
      "constraints": ["Recipient determination rule is currently unspecified; may require additional stakeholders beyond attendees"],
      "confidence": "low"
    },
    {
      "target": "A7 - Send Summary Email",
      "rationale": "Once the final summary and recipient list are confirmed, automated email dispatch can be triggered without manual sending steps.",
      "required_data": ["Final meeting summary", "Confirmed recipient list", "Email system integration"],
      "constraints": ["Human approval step may still be needed before automated send", "Email system must be accessible programmatically"],
      "confidence": "high"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "No defined trigger or signal for when the meeting has officially ended and the summarisation process should begin.",
      "impact": "Process start is ambiguous; automation cannot be reliably initiated without a clear trigger event."
    },
    {
      "id": "G2",
      "description": "The system or tool used by the minute taker to collect notes or transcripts is not specified.",
      "impact": "Cannot design integrations or automations for note collection without knowing the tooling."
    },
    {
      "id": "G3",
      "description": "The method for determining the recipient list is unspecified; it is unclear whether it is derived from the attendee list, a predefined group, or manual selection.",
      "impact": "Recipient determination step cannot be automated or standardised without a defined rule."
    },
    {
      "id": "G4",
      "description": "No time limit or SLA is defined for sending the summary email after the meeting concludes.",
      "impact": "Cannot implement deadline monitoring, escalation, or SLA breach alerting without a defined timeframe."
    },
    {
      "id": "G5",
      "description": "The role responsible for determining and confirming recipients is not clearly assigned.",
      "impact": "Accountability for this step is unclear, which may cause delays or omissions in distribution."
    },
    {
      "id": "G6",
      "description": "It is unknown whether a formal approval step exists before the summary email is sent beyond resolving unclear items.",
      "impact": "If an approval gate is implicitly expected, sending without it could create compliance or governance issues."
    }
  ]
}
